package ai.applypilot.tracking;

import ai.applypilot.ai.AiProviderException;
import ai.applypilot.jobs.SavedJob;
import ai.applypilot.jobs.SavedJobRepository;
import ai.applypilot.bundles.ApplicationBundleRepository;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
