@RestController
@RequestMapping("/api")
public class Phase4Controller {
    private final JdbcTemplate jdbc;
    private final SavedJobRepository jobs;
    private final ApplicationBundleRepository bundles;
    private final ObjectMapper mapper;
    private final InterviewAnswerDraftService answerDrafts;

    public Phase4Controller(JdbcTemplate jdbc, SavedJobRepository jobs, ApplicationBundleRepository bundles, ObjectMapper mapper, InterviewAnswerDraftService answerDrafts) {
        this.jdbc = jdbc; this.jobs = jobs; this.bundles = bundles; this.mapper = mapper; this.answerDrafts=answerDrafts;
    }
    private UUID owner(Authentication a) { return (UUID)a.getPrincipal(); }
    private Map<String,Object> application(UUID id, UUID user) {
        return jdbc.query("SELECT * FROM application_tracking WHERE id=? AND user_id=?", rs -> rs.next()?row(rs):Optional.<Map<String,Object>>empty(),id,user)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Application not found"));
    }
    private Optional<Map<String,Object>> row(ResultSet rs) throws java.sql.SQLException {
        var m=new LinkedHashMap<String,Object>(); var md=rs.getMetaData();
        for(int i=1;i<=md.getColumnCount();i++){Object v=rs.getObject(i);if(v instanceof java.sql.Timestamp t)v=t.toInstant();m.put(md.getColumnLabel(i).toLowerCase(Locale.ROOT),v);}
        return Optional.of(m);
    }

    public record CreateApplication(UUID jobId, UUID bundleId, String status, String notes) {}
    @PostMapping("/applications") @ResponseStatus(HttpStatus.CREATED)
    public Map<String,Object> create(Authentication a,@RequestBody CreateApplication req) {
        UUID user=owner(a); SavedJob job=jobs.findByIdAndUserId(req.jobId(),user).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found"));
        String status=req.status()==null?"SAVED":req.status(); validateStatus(status);
        if(!ApplicationTrackingPolicy.mayMarkApplied(status,false)) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"APPLIED requires explicit candidate confirmation");
        UUID resumeId=null; Integer version=null; String answers="[]"; String certificationSnapshot="[]"; boolean certificationsApproved=false;
        if(req.bundleId()!=null){var bundle=bundles.findByIdAndUserId(req.bundleId(),user).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Bundle not found"));
            if(!bundle.getJobId().equals(job.getId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Bundle belongs to another job");
            resumeId=bundle.getResumeId();version=bundle.getResumeVersionNumber();answers=write(bundle.getApplicationAnswers());certificationSnapshot=write(bundle.getCertificationsSnapshot());certificationsApproved=bundle.isCertificationsApproved();}
        UUID id=UUID.randomUUID(); final UUID rid=resumeId; final Integer ver=version; final String snap=answers; final String certSnap=certificationSnapshot; final boolean certApproved=certificationsApproved;
        try { jdbc.update("INSERT INTO application_tracking(id,user_id,job_id,bundle_id,status,resume_id,resume_version_number,answer_snapshot,certifications_snapshot,certifications_approved,notes,applied_at) VALUES (?,?,?,?,?, ?,?,?::jsonb,?::jsonb,?,?,CASE WHEN ?='APPLIED' THEN CURRENT_TIMESTAMP END)",id,user,job.getId(),req.bundleId(),status,rid,ver,snap,certSnap,certApproved,req.notes(),status); }
        catch(org.springframework.dao.DuplicateKeyException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,"An application already exists for this job");}
        if(!status.equals("SAVED")) notify(user,"STATUS_CHANGE","Application status updated",job.getTitle()+" · "+status,id,null);
        return application(id,user);
    }

    @GetMapping("/applications") public List<Map<String,Object>> listApplications(Authentication a){return jdbc.query("SELECT at.*,j.title AS job_title,j.company AS company FROM application_tracking at JOIN saved_jobs j ON j.id=at.job_id WHERE at.user_id=? ORDER BY at.updated_at DESC",(rs,n)->row(rs).orElse(Map.of()),owner(a));}
    @PatchMapping("/applications/{id}") public Map<String,Object> update(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object> req){
        UUID user=owner(a);Map<String,Object> current=application(id,user);String status=(String)req.get("status");
        if(status!=null){validateStatus(status);if(!ApplicationTrackingPolicy.mayMarkApplied(status,Boolean.TRUE.equals(req.get("candidateConfirmedApplied"))))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Candidate confirmation is required to record APPLIED");}
        boolean certApproved=Boolean.TRUE.equals(current.get("certifications_approved"))||Boolean.TRUE.equals(req.get("certificationsApproved"));
        if("READY_FOR_REVIEW".equals(status)&&!readList(Objects.toString(current.get("certifications_snapshot"),"[]")).isEmpty()&&!certApproved)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Candidate review is required before including certification metadata in application preparation.");
        OffsetDateTime interviewScheduled=null; if(req.get("interviewScheduledAt") instanceof String s&&!s.isBlank()){try{interviewScheduled=OffsetDateTime.parse(s);}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"interviewScheduledAt must be an ISO-8601 date-time");}}
        jdbc.update("UPDATE application_tracking SET status=COALESCE(?,status), notes=COALESCE(?,notes), certifications_approved=?, interview_scheduled_at=COALESCE(?,interview_scheduled_at), applied_at=CASE WHEN ?='APPLIED' THEN COALESCE(applied_at,CURRENT_TIMESTAMP) ELSE applied_at END, shortlisted_at=CASE WHEN ?='SHORTLISTED' THEN COALESCE(shortlisted_at,CURRENT_TIMESTAMP) ELSE shortlisted_at END, interview_at=CASE WHEN ?='INTERVIEW' THEN COALESCE(interview_at,CURRENT_TIMESTAMP) ELSE interview_at END, rejected_at=CASE WHEN ?='REJECTED' THEN COALESCE(rejected_at,CURRENT_TIMESTAMP) ELSE rejected_at END, offer_at=CASE WHEN ?='OFFER' THEN COALESCE(offer_at,CURRENT_TIMESTAMP) ELSE offer_at END, withdrawn_at=CASE WHEN ?='WITHDRAWN' THEN COALESCE(withdrawn_at,CURRENT_TIMESTAMP) ELSE withdrawn_at END, updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?",status,req.get("notes"),certApproved,interviewScheduled,status,status,status,status,status,status,id,user);
        if(status!=null){notify(user,"STATUS_CHANGE","Application status updated",status,id,null);if(status.equals("PREPARING")||status.equals("READY_FOR_REVIEW"))notify(user,"PREPARATION","Application preparation reminder",status,id,null);}if(interviewScheduled!=null)notify(user,"INTERVIEW","Upcoming interview", "Interview scheduled for "+interviewScheduled,id,interviewScheduled.toInstant());return application(id,user);
    }
    private void validateStatus(String s){if(!ApplicationTrackingPolicy.validStatus(s))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown application status");}

    @GetMapping("/applications/dashboard") public Map<String,Object> dashboard(Authentication a){
        UUID user=owner(a);var counts=new LinkedHashMap<String,Long>();jdbc.query("SELECT status,COUNT(*) c FROM application_tracking WHERE user_id=? GROUP BY status",rs->{counts.put(rs.getString(1),rs.getLong(2));},user);
        long total=counts.values().stream().mapToLong(Long::longValue).sum(), applied=counts.getOrDefault("APPLIED",0L)+counts.getOrDefault("SHORTLISTED",0L)+counts.getOrDefault("INTERVIEW",0L)+counts.getOrDefault("REJECTED",0L)+counts.getOrDefault("OFFER",0L)+counts.getOrDefault("WITHDRAWN",0L), interviews=counts.getOrDefault("INTERVIEW",0L), offers=counts.getOrDefault("OFFER",0L), rejects=counts.getOrDefault("REJECTED",0L);
        var weekly=jdbc.queryForList("SELECT date_trunc('week',created_at) period,COUNT(*) count FROM application_tracking WHERE user_id=? AND created_at>=CURRENT_DATE-INTERVAL '7 days' GROUP BY period ORDER BY period",user);
        var monthly=jdbc.queryForList("SELECT date_trunc('month',created_at) period,COUNT(*) count FROM application_tracking WHERE user_id=? AND created_at>=CURRENT_DATE-INTERVAL '12 months' GROUP BY period ORDER BY period",user);
        return Map.of("total",total,"byStatus",counts,"weeklyActivity",weekly,"monthlyActivity",monthly,"interviews",interviews,"offers",offers,"rejections",rejects,"responseRate",applied==0?0.0:(interviews+offers+rejects)*100.0/applied,"interviewRate",applied==0?0.0:interviews*100.0/applied);
    }

    public record FollowupRequest(OffsetDateTime dueAt,Boolean reminderEnabled,String note){}
    @PostMapping("/applications/{id}/followups") @ResponseStatus(HttpStatus.CREATED)
    @Transactional
    public Map<String,Object> addFollowup(Authentication a,@PathVariable UUID id,@RequestBody FollowupRequest r){UUID u=owner(a);application(id,u);if(r.dueAt()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"dueAt is required");UUID fid=UUID.randomUUID();jdbc.update("INSERT INTO application_followups(id,user_id,application_id,due_at,reminder_enabled,note) VALUES(?,?,?,?,?,?)",fid,u,id,r.dueAt(),!Boolean.FALSE.equals(r.reminderEnabled()),r.note());
        if(!Boolean.FALSE.equals(r.reminderEnabled())&&preferences(u).followupReminders())insertFollowupReminder(u,id,fid,r.note(),r.dueAt());return jdbc.queryForMap("SELECT * FROM application_followups WHERE id=? AND user_id=?",fid,u);}
    @GetMapping("/applications/{id}/followups") public List<Map<String,Object>> followups(Authentication a,@PathVariable UUID id){UUID u=owner(a);application(id,u);return jdbc.queryForList("SELECT * FROM application_followups WHERE application_id=? AND user_id=? ORDER BY due_at",id,u);}
    @GetMapping("/followups") public Map<String,Object> followupLists(Authentication a){UUID u=owner(a);return Map.of("overdue",jdbc.queryForList("SELECT * FROM application_followups WHERE user_id=? AND completed_at IS NULL AND due_at<CURRENT_TIMESTAMP ORDER BY due_at",u),"upcoming",jdbc.queryForList("SELECT * FROM application_followups WHERE user_id=? AND completed_at IS NULL AND due_at>=CURRENT_TIMESTAMP ORDER BY due_at",u),"completed",jdbc.queryForList("SELECT * FROM application_followups WHERE user_id=? AND completed_at IS NOT NULL ORDER BY completed_at DESC",u));}
    public record FollowupUpdate(OffsetDateTime dueAt,Boolean reminderEnabled,String note,Boolean completed){}
    @PatchMapping("/followups/{id}") @Transactional public Map<String,Object> updateFollowup(Authentication a,@PathVariable UUID id,@RequestBody FollowupUpdate req){UUID u=owner(a);int n;if(req.completed()==null){n=jdbc.update("UPDATE application_followups SET due_at=COALESCE(?,due_at), reminder_enabled=COALESCE(?,reminder_enabled), note=COALESCE(?,note), updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?",req.dueAt(),req.reminderEnabled(),req.note(),id,u);}else{n=jdbc.update("UPDATE application_followups SET due_at=COALESCE(?,due_at), reminder_enabled=COALESCE(?,reminder_enabled), note=COALESCE(?,note), completed_at=CASE WHEN ? THEN COALESCE(completed_at,CURRENT_TIMESTAMP) ELSE NULL END, updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?",req.dueAt(),req.reminderEnabled(),req.note(),req.completed(),id,u);}if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Follow-up not found");var row=jdbc.queryForMap("SELECT * FROM application_followups WHERE id=? AND user_id=?",id,u);boolean active=Boolean.TRUE.equals(row.get("reminder_enabled"))&&row.get("completed_at")==null&&preferences(u).followupReminders();if(active){jdbc.update("UPDATE in_app_notifications SET scheduled_at=?,body=COALESCE(?,body),read_at=NULL WHERE followup_id=? AND user_id=?",row.get("due_at"),row.get("note"),id,u);int reminders=jdbc.queryForObject("SELECT count(*) FROM in_app_notifications WHERE followup_id=? AND user_id=?",Integer.class,id,u);if(reminders==0){OffsetDateTime due=jdbc.queryForObject("SELECT due_at FROM application_followups WHERE id=? AND user_id=?",OffsetDateTime.class,id,u);insertFollowupReminder(u,(UUID)row.get("application_id"),id,(String)row.get("note"),due);}}else{jdbc.update("UPDATE in_app_notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE followup_id=? AND user_id=?",id,u);}return row;}

    @GetMapping("/applications/{id}/interview-prep") public Map<String,Object> interviewPrep(Authentication a,@PathVariable UUID id){UUID u=owner(a);var app=application(id,u);UUID jobId=(UUID)app.get("job_id");SavedJob job=jobs.findByIdAndUserId(jobId,u).orElseThrow();var existing=jdbc.query("SELECT id,user_id,application_id,questions::text AS questions,progress::text AS progress,created_at,updated_at FROM interview_preparations WHERE application_id=? AND user_id=?",rs->rs.next()?row(rs).orElse(Map.of()):null,id,u);if(existing!=null)return existing;
        List<Map<String,String>> qs=new ArrayList<>();String description=Objects.toString(job.getDescription(),"");
        String tech=job.getRequiredSkills().stream().findFirst().orElse("the technical requirements listed in the job description");
        qs.add(q("TECHNICAL","How would you approach a task involving "+tech+"? Refer to a verified project, work example, or explain where you need to learn more.","Job requirement: "+tech));qs.add(q("HR","What interests you about this role"+(job.getCompany()==null||job.getCompany().isBlank()?"":" at "+job.getCompany())+"?","Saved job details"));qs.add(q("BEHAVIORAL","Describe a work or project challenge and the steps you personally took. Use only a verified example.","Candidate work or project evidence required"));qs.add(q("PROJECT","Which saved project best relates to this role? Use details from your verified profile only.","Candidate project evidence required"));qs.add(q("RESUME","Which experience in your selected resume version supports your application for this role?","Exact resume version required"));
        UUID pid=UUID.randomUUID();jdbc.update("INSERT INTO interview_preparations(id,user_id,application_id,questions,progress) VALUES(?,?,?,?::jsonb,'{}'::jsonb)",pid,u,id,write(qs));return jdbc.queryForMap("SELECT id,user_id,application_id,questions::text AS questions,progress::text AS progress,created_at,updated_at FROM interview_preparations WHERE id=?",pid);}
    @PatchMapping("/applications/{id}/interview-prep") public Map<String,Object> updateInterview(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object> body){UUID u=owner(a);application(id,u);String answer=Objects.toString(body.get("answer"),"");String questionId=Objects.toString(body.get("questionId"),"");if(answer.length()>5000||questionId.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A questionId and answer up to 5000 characters are required");var prep=interviewPrep(a,id);UUID pid=(UUID)prep.get("id");String progress=jdbc.queryForObject("SELECT progress::text FROM interview_preparations WHERE id=?",String.class,pid);Map<String,Object> p=readMap(progress);p.put(questionId,Map.of("answer",answer,"editedByCandidate",true));jdbc.update("UPDATE interview_preparations SET progress=?::jsonb,updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?",write(p),pid,u);return jdbc.queryForMap("SELECT id,user_id,application_id,questions::text AS questions,progress::text AS progress,created_at,updated_at FROM interview_preparations WHERE id=?",pid);}

    @PostMapping("/applications/{id}/interview-prep/draft") public InterviewAnswerDraftService.Draft draftInterviewAnswer(Authentication a,@PathVariable UUID id,@RequestBody Map<String,String> req){UUID u=owner(a);var app=application(id,u);String qid=req.get("questionId");if(qid==null||qid.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"questionId is required");if(app.get("resume_id")==null||app.get("resume_version_number")==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"This application has no exact resume version for evidence-based drafting.");UUID resumeId=(UUID)app.get("resume_id");int version=((Number)app.get("resume_version_number")).intValue();String text=jdbc.query("SELECT rv.extracted_text FROM resume_versions rv JOIN resumes r ON r.id=rv.resume_id WHERE rv.resume_id=? AND rv.version_number=? AND r.user_id=?",rs->rs.next()?rs.getString(1):null,resumeId,version,u);if(text==null||text.isBlank())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"The selected resume version has no extracted evidence text.");var prep=interviewPrep(a,id);List<Map<String,Object>> questions=readList(Objects.toString(prep.get("questions"),"[]"));String question=questions.stream().filter(q->qid.equals(q.get("id"))).map(q->Objects.toString(q.get("question"),"")).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Interview question not found."));List<String> excerpts=Arrays.stream(text.split("\\R|(?<=[.!?])\\s+")).map(String::trim).filter(s->s.length()>12).limit(8).map(s->s.substring(0,Math.min(1000,s.length()))).toList();try{return answerDrafts.draft(question,resumeId,version,excerpts);}catch(AiProviderException ex){HttpStatus status=ex.kind()==AiProviderException.Kind.INVALID_RESPONSE?HttpStatus.UNPROCESSABLE_ENTITY:HttpStatus.SERVICE_UNAVAILABLE;throw new ResponseStatusException(status,ex.kind()==AiProviderException.Kind.INVALID_RESPONSE?"No supported draft could be produced. Edit an answer yourself using verified evidence.":"Local AI is disabled or unavailable. You can write the answer yourself.");}}
    private Map<String,String> q(String category,String question,String evidence){return Map.of("id",UUID.randomUUID().toString(),"category",category,"question",question,"evidenceRequirement",evidence);}

    @GetMapping("/jobs/{jobId}/skill-gaps") public Map<String,Object> skillGaps(Authentication a,@PathVariable UUID jobId){UUID u=owner(a);SavedJob j=jobs.findByIdAndUserId(jobId,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found"));Set<String> verified=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);jdbc.query("SELECT name FROM skill_records WHERE user_id=? AND verified=TRUE",rs->{verified.add(rs.getString(1));},u);
        var required=gapList(j.getRequiredSkills(),verified,"REQUIRED");var preferred=gapList(j.getPreferredSkills(),verified,"PREFERRED");List<Map<String,Object>> gaps=new ArrayList<>();gaps.addAll(required);gaps.addAll(preferred);var prog=jdbc.queryForList("SELECT skill,progress FROM skill_gap_progress WHERE user_id=? AND job_id=?",u,jobId);Map<String,String> states=new HashMap<>();for(var row:prog)states.put(Objects.toString(row.get("skill")),Objects.toString(row.get("progress")));for(var gap:gaps)gap.put("progress",states.getOrDefault(gap.get("skill"),"NOT_STARTED"));return Map.of("verifiedSkills",verified,"gaps",gaps,"source","saved job skill requirements and verified candidate skills");}
    private List<Map<String,Object>> gapList(List<String> skills,Set<String> verified,String kind){List<Map<String,Object>> out=new ArrayList<>();for(String s:skills)out.add(new LinkedHashMap<>(Map.of("skill",s,"kind",kind,"status",verified.contains(s)?"VERIFIED_MATCH":"MISSING_OR_UNVERIFIED","priority",kind.equals("REQUIRED")?"HIGH":"NORMAL","practiceTopic", "Practice the role's "+s+" requirement using a real project or coursework example; do not claim proficiency without evidence.")));return out;}
    @PutMapping("/jobs/{jobId}/skill-gaps/{skill}") public Map<String,Object> updateSkillGap(Authentication a,@PathVariable UUID jobId,@PathVariable String skill,@RequestBody Map<String,String> req){UUID u=owner(a);jobs.findByIdAndUserId(jobId,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found"));String state=req.get("progress");if(!Set.of("NOT_STARTED","IN_PROGRESS","PRACTICED","ADDRESSED").contains(state))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid progress");jdbc.update("INSERT INTO skill_gap_progress(user_id,job_id,skill,progress) VALUES(?,?,?,?) ON CONFLICT(user_id,job_id,skill) DO UPDATE SET progress=EXCLUDED.progress,updated_at=CURRENT_TIMESTAMP",u,jobId,skill,state);return Map.of("jobId",jobId,"skill",skill,"progress",state);}

    public record NotificationPreferences(Boolean followupReminders,Boolean interviewReminders,Boolean statusChanges,Boolean preparationReminders,Boolean certificationReminders){}
    private record Preferences(boolean followupReminders,boolean interviewReminders,boolean statusChanges,boolean preparationReminders,boolean certificationReminders){}
    private Preferences preferences(UUID user){return jdbc.query("SELECT followup_reminders,interview_reminders,status_changes,preparation_reminders,certification_reminders FROM user_notification_preferences WHERE user_id=?",rs->rs.next()?new Preferences(rs.getBoolean(1),rs.getBoolean(2),rs.getBoolean(3),rs.getBoolean(4),rs.getBoolean(5)):new Preferences(true,true,true,true,true),user);}
    @GetMapping("/notification-preferences") public Map<String,Object> getNotificationPreferences(Authentication a){var p=preferences(owner(a));return Map.of("followupReminders",p.followupReminders(),"interviewReminders",p.interviewReminders(),"statusChanges",p.statusChanges(),"preparationReminders",p.preparationReminders(),"certificationReminders",p.certificationReminders());}
    @PutMapping("/notification-preferences") public Map<String,Object> putNotificationPreferences(Authentication a,@RequestBody NotificationPreferences p){UUID u=owner(a);boolean f=!Boolean.FALSE.equals(p.followupReminders()),i=!Boolean.FALSE.equals(p.interviewReminders()),s=!Boolean.FALSE.equals(p.statusChanges()),r=!Boolean.FALSE.equals(p.preparationReminders()),c=!Boolean.FALSE.equals(p.certificationReminders());jdbc.update("INSERT INTO user_notification_preferences(user_id,followup_reminders,interview_reminders,status_changes,preparation_reminders,certification_reminders) VALUES(?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET followup_reminders=EXCLUDED.followup_reminders,interview_reminders=EXCLUDED.interview_reminders,status_changes=EXCLUDED.status_changes,preparation_reminders=EXCLUDED.preparation_reminders,certification_reminders=EXCLUDED.certification_reminders,updated_at=CURRENT_TIMESTAMP",u,f,i,s,r,c);return getNotificationPreferences(a);}
    @GetMapping("/notifications") public List<Map<String,Object>> notifications(Authentication a){return jdbc.queryForList("SELECT * FROM in_app_notifications WHERE user_id=? AND read_at IS NULL AND (scheduled_at IS NULL OR scheduled_at<=CURRENT_TIMESTAMP) ORDER BY created_at DESC LIMIT 100",owner(a));}
    @PatchMapping("/notifications/{id}/read") public Map<String,Object> readNotification(Authentication a,@PathVariable UUID id){UUID u=owner(a);int n=jdbc.update("UPDATE in_app_notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE id=? AND user_id=?",id,u);if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found");return jdbc.queryForMap("SELECT * FROM in_app_notifications WHERE id=? AND user_id=?",id,u);}
    private void notify(UUID user,String kind,String title,String body,UUID app,Instant scheduled){var p=preferences(user);boolean enabled=switch(kind){case "FOLLOW_UP"->p.followupReminders();case "INTERVIEW"->p.interviewReminders();case "PREPARATION"->p.preparationReminders();default->p.statusChanges();};if(!enabled)return;jdbc.update("INSERT INTO in_app_notifications(user_id,kind,title,body,application_id,scheduled_at) VALUES(?,?,?,?,?,?)",user,kind,title,body,app,scheduled==null?null:OffsetDateTime.ofInstant(scheduled,java.time.ZoneOffset.UTC));}
    private void insertFollowupReminder(UUID user,UUID app,UUID followup,String note,OffsetDateTime due){jdbc.update("INSERT INTO in_app_notifications(user_id,kind,title,body,application_id,followup_id,scheduled_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(followup_id) WHERE followup_id IS NOT NULL AND kind='FOLLOW_UP' DO UPDATE SET body=EXCLUDED.body,scheduled_at=EXCLUDED.scheduled_at,read_at=NULL",user,"FOLLOW_UP","Follow-up reminder",note==null?"Application follow-up is due":note,app,followup,due);}
    private String write(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException("Could not encode application data");}}
    private Map<String,Object> readMap(String s){try{return mapper.readValue(s,new TypeReference<>(){});}catch(Exception e){return new LinkedHashMap<>();}}
    private List<Map<String,Object>> readList(String s){try{return mapper.readValue(s,new TypeReference<>(){});}catch(Exception e){return List.of();}}
}
